package me.never.blockparty;
import org.bukkit.command.*;import org.bukkit.entity.Player;
public final class BPCommand implements CommandExecutor{final Game g;BPCommand(Game g){this.g=g;}public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage("Only players can use this command.");return true;}String x=a.length==0?"join":a[0].toLowerCase();switch(x){case"join"->g.join(p);case"leave"->g.leave(p);case"status"->g.status(p);case"start"->{if(p.hasPermission("neverblockparty.admin"))g.start();else p.sendMessage("§cNo permission.");}case"stop"->{if(p.hasPermission("neverblockparty.admin"))g.stop();else p.sendMessage("§cNo permission.");}default->p.sendMessage("§b/bp join §7| §b/bp leave §7| §b/bp status §7| §b/bp start §7| §b/bp stop");}return true;}}